{
  "title": "Murder in Redwater",
  "language": "en",
  "recommended_level": "2",
  "hook": "The wealthy merchant Marcus Redwood is found dead in his home, and the local authorities are overwhelmed.",
  "npcs": [
    {
      "name": "Mayor Tomlin",
      "role": "Provides information and tasks for the party, represents the town's leadership."
    },
    {
      "name": "Sheriff Grady",
      "role": "Provides law enforcement expertise and helps with the investigation."
    },
    {
      "name": "Dr. Eliza Peters",
      "role": "Provides medical expertise and helps with the investigation."
    },
    {
      "name": "Marcus Redwood's Wife",
      "role": null
    },
    {
      "name": "Marcus Redwood's Son",
      "role": null
    },
    {
      "name": "Marcus Redwood's Daughter",
      "role": null
    },
    {
      "name": "Jack Kessler",
      "role": "Owns a shipping company and may have had a motive to kill Redwood to prevent him from revealing the smuggling operation."
    },
    {
      "name": "Sarah Lowell",
      "role": "Owns a competing trading company and may have had a motive to eliminate Redwood as a rival."
    }
  ],
  "locations": [
    "Redwood's Mansion",
    "Town Center",
    "Trading Company Office",
    "Redwood Trading Company"
  ],
  "threats": [
    "Hired Assassin",
    "Cultists",
    "Smugglers"
  ],
  "rewards": [
    "Amulet of Proof against Detection and Location",
    "Ring of Protection",
    "Wand of Magic Missiles",
    "Potion of Healing"
  ]
}

